Here is a demonstration of a Path Traversal vulnerability caused by improper use of the `java.io.File` API.

The bad code directly concatenates user input with a base directory path. An attacker can provide input like `../../../../etc/passwd` to "traverse" out of the intended directory and access sensitive system files.

```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.OutputStream;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class UnsafeFileDownloadServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // Get the filename from a user-controlled parameter.
        String filename = request.getParameter("filename");

        // Define the base directory where user files are stored.
        String baseDirectory = "/WEB-INF/user_uploads/";

        // Directly concatenate user input with the base path.
        // This line is vulnerable to Path Traversal. An attacker can provide
        // input like "../../../../../etc/passwd" to read arbitrary files.
        File file = new File(baseDirectory + filename);

        if (file.exists() && !file.isDirectory()) {
            response.setContentType("application/octet-stream");
            response.setHeader("Content-Disposition", "attachment; filename=\"" + file.getName() + "\"");

            try (FileInputStream fileInputStream = new FileInputStream(file);
                 OutputStream out = response.getOutputStream()) {

                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fileInputStream.read(buffer)) != -1) {
                    out.write(buffer, 0, bytesRead);
                }
            }
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found.");
        }
    }
}
```

***

The good code fixes the vulnerability by validating the file path. It resolves the canonical path (which processes `..` and other special characters) of the requested file and ensures that it still resides within the intended base directory before serving it.

```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.OutputStream;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SafeFileDownloadServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // Get the filename from a user-controlled parameter.
        String filename = request.getParameter("filename");

        // Define the base directory where user files are stored.
        File baseDir = new File("/WEB-INF/user_uploads/");
        File requestedFile = new File(baseDir, filename);

        // **SECURITY FIX**: Validate the file's canonical path.
        // This resolves ".." sequences and ensures the requested file is actually
        // located inside the intended base directory.
        String canonicalBasePath = baseDir.getCanonicalPath();
        String canonicalFilePath = requestedFile.getCanonicalPath();

        if (!canonicalFilePath.startsWith(canonicalBasePath)) {
            // If the path is outside the base directory, it's a traversal attempt.
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid file path requested.");
            return;
        }

        if (requestedFile.exists() && !requestedFile.isDirectory()) {
             response.setContentType("application/octet-stream");
             response.setHeader("Content-Disposition", "attachment; filename=\"" + requestedFile.getName() + "\"");

            try (FileInputStream fileInputStream = new FileInputStream(requestedFile);
                 OutputStream out = response.getOutputStream()) {

                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fileInputStream.read(buffer)) != -1) {
                    out.write(buffer, 0, bytesRead);
                }
            }
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found.");
        }
    }
}
